CREATE TABLE GamePlayabilityProfile(GameID INTEGER PRIMARY KEY, SpecialAccessoryRequired BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, ControlSchemeRisk VARCHAR, RhythmFlag BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, SHMUPFlag BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, SoulslikeFlag BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, MitigationAvailable BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, PlayabilityNotes VARCHAR);
